-- PostgreSQL script made by Puddle from the project's DBML

CREATE TYPE "order_status" AS ENUM ('pending', 'paid', 'shipped', 'cancelled');

CREATE TABLE "customers" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) NOT NULL UNIQUE,
  "name" varchar(100) NOT NULL,
  "country" char(2) DEFAULT 'GB',
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "orders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" integer NOT NULL,
  "status" "order_status" DEFAULT 'pending' NOT NULL,
  "total" numeric(10,2) NOT NULL CHECK (total >= 0),
  "ordered_at" timestamp NOT NULL
);

CREATE INDEX "orders_by_customer" ON "orders" ("customer_id", "ordered_at");

CREATE TABLE "products" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sku" varchar(32) NOT NULL UNIQUE,
  "name" varchar NOT NULL,
  "price" numeric(10,2) NOT NULL
);

CREATE TABLE "order_items" (
  "order_id" integer NOT NULL,
  "product_id" integer NOT NULL,
  "quantity" integer DEFAULT 1 NOT NULL,
  PRIMARY KEY ("order_id", "product_id")
);

ALTER TABLE "orders" ADD FOREIGN KEY ("customer_id") REFERENCES "customers" ("id");
ALTER TABLE "order_items" ADD FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE CASCADE;
ALTER TABLE "order_items" ADD FOREIGN KEY ("product_id") REFERENCES "products" ("id");

COMMENT ON TABLE "customers" IS 'Everyone who has signed up';
